// Loop over EVERY binary key on the incoming item (not just quoteFile/quoteFile0),
// so any number of attached files each become their own item downstream.
const item = $input.first();
const source = $('Normalize Input1').first().json;
const binaryKeys = Object.keys(item.binary || {});

if (binaryKeys.length === 0) {
  // No attachment at all — keep today's plain-text passthrough behavior:
  // exactly one item, no mimeType, no binary.
  return [{
    json: {
      message: source.message,
      sessionId: source.sessionId,
    },
  }];
}

return binaryKeys.map((key) => {
  const meta = item.binary[key];
  return {
    json: {
      message: source.message,
      sessionId: source.sessionId,
      mimeType: meta.mimeType,
    },
    binary: {
      data: meta,
    },
  };
});

const source = $('Normalize Input1').first().json;
const current = $input.first().json;

// Two paths reach this node:
// 1) Attachment(s) went through extraction + the Aggregate node — combinedExtractedText
//    is an array of per-file extracted text (one entry per attachment).
// 2) No attachment (or an unrecognized file type) — the Switch's fallback output sent
//    the item here directly, so combinedExtractedText doesn't exist. Same as today.
const combined = current.combinedExtractedText;
const extractedRaw = Array.isArray(combined)
  ? combined.filter(Boolean).join('\n\n')
  : (current.text || current.data || current.content || '');
const extractedText = String(extractedRaw).trim().slice(0, 4000);

return [{
  json: {
    message: source.message,
    sessionId: source.sessionId,
    extractedText,
  },
}];

// N8N CRASH FIX: use .first() instead of .item, same as elsewhere in this workflow
const sessionId = $('Normalize Input1').first().json.sessionId || null;
// The place the customer picked, carried through so ranking can measure real distance to
// each business's service area rather than comparing suburb names.
let place = null;
try {
  place = JSON.parse($('Normalize Input1').first().json.place || 'null');
} catch (error) {
  place = null;
}

// The Structured Output Parser + OpenAI json_object mode already guarantee valid,
// schema-shaped JSON here — $json.output is the parsed object directly.
const parsed = $input.first().json.output || {};

// One checklist for both kinds of request. 'compare a quote I already have' stopped being a
// separate flow with a separate agent: it is this same brief plus an optional existingPrice,
// which is a field, not a branch. siteAccess is conditional — see isMissing below.
const FIELDS = ['suburb', 'fenceType', 'lengthMeters', 'heightMm', 'removeOldFence', 'siteAccess'];

// The canonical question + option set per field, identical to the ones the agent's
// prompt hands it. Kept here so this node can ask a field itself when the model
// tries to skip ahead — the choices are fixed, they never needed the LLM.
const ASK = {
  suburb: { message: 'Which suburb is the fence going in?', options: [] },
  fenceType: {
    message: 'What type of fence are you after?',
    options: [
      { label: 'Timber', value: 'Timber' },
      { label: 'Colorbond', value: 'Colorbond' },
      { label: 'Aluminium', value: 'Aluminium' },
      { label: 'Pool Fencing', value: 'Pool Fencing' },
      { label: 'Security/Chainmesh', value: 'Security/Chainmesh' },
      { label: 'Rural', value: 'Rural' },
    ],
  },
  lengthMeters: {
    // The four runs people actually ask for, plus a way out. Every value is a real length in
    // metres, never a bucket, because the rate is per metre and a range would price a job
    // nobody described. 'Other' is answered in a text box on the client rather than sent.
    message: 'How long is the fence?',
    options: [
      { label: '10m', value: 10 },
      { label: '20m', value: 20 },
      { label: '30m', value: 30 },
      { label: '40m', value: 40 },
      { label: 'Other', value: '__other__' },
    ],
  },
  heightMm: {
    // Exactly the heights businesses publish a per-metre rate against (rates are keyed 1.2,
    // 1.5, 1.8, 2.1). Offering a height nobody prices only produces an empty result page.
    message: 'What height are you after?',
    options: [
      { label: '1.3m', value: 1300 },
      { label: '1.5m', value: 1500 },
      { label: '1.8m', value: 1800 },
      { label: '2.1m', value: 2100 },
    ],
  },
  removeOldFence: {
    message: 'Is there an old fence that needs removing?',
    options: [
      { label: 'Yes, please remove it', value: true },
      { label: 'No, starting fresh', value: false },
    ],
  },
  siteAccess: {
    message: "How's the access along the fence line?",
    options: [
      { label: 'Easy (flat, clear)', value: 'easy' },
      { label: 'Difficult (sloped, tight)', value: 'difficult' },
    ],
  },
};

// What the client already has on screen. A turn that quietly drops an established value back
// to null is what produced "it asked me for the suburb again" — restore it before anything
// downstream counts what's still missing or decides which question is due.
let known = {};
try {
  known = JSON.parse($('Normalize Input1').first().json.knownChecklist || '{}') || {};
} catch (error) {
  known = {};
}

const merged = { ...(parsed.checklist || {}) };
for (const field of FIELDS) {
  if ((merged[field] === null || merged[field] === undefined) && known[field] !== null && known[field] !== undefined) {
    merged[field] = known[field];
  }
}
// A value mined from a quote document arrives written the way the document wrote it:
// "$3,309.90", "25m", "1800mm", "1.8H". The agent is asked for plain numbers, and asking is
// not getting — a string here reaches the ranking step as NaN and prices nothing at all, with
// no error anywhere to explain why.
const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (value === null || value === undefined) return null;
  // Thousands separators first, so "3,309.90" does not read as two numbers.
  const text = String(value).replace(/,(?=\d{3}\b)/g, '');
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const parsed = Number(match[0]);
  return Number.isFinite(parsed) ? parsed : null;
};

for (const field of ['lengthMeters', 'heightMm', 'existingPrice']) {
  if (merged[field] !== null && merged[field] !== undefined) {
    const parsed = toNumber(merged[field]);
    // A value that holds no number at all is worse than none: it looks answered and prices
    // nothing. Dropping it back to null makes the agent ask.
    merged[field] = parsed;
  }
}

// Documents describe the fence, they do not name our options: "standard timber fence paling",
// "Colorbond infill", "chain wire". Ranking matches the business's enabledTypes on an exact
// slug, so anything not snapped back to one of these six quietly matches nobody. Specific
// before generic — "glass pool fence" is pool fencing, not timber.
const FENCE_TYPE_HINTS = [
  ['Colorbond', /colou?rbond/i],
  ['Pool Fencing', /pool|glass/i],
  ['Security/Chainmesh', /chain ?(?:mesh|wire|link)|security|mesh/i],
  ['Aluminium', /alumin(?:i)?um|slat/i],
  ['Rural', /rural|post and wire|farm|paddock|stock fence/i],
  ['Timber', /timber|paling|hardwood|treated pine|\bpine\b|\bwood/i],
];

if (typeof merged.fenceType === 'string' && merged.fenceType.trim()) {
  const asked = ASK.fenceType.options.map((option) => option.value);
  const exact = asked.find((option) => option.toLowerCase() === merged.fenceType.trim().toLowerCase());
  if (exact) {
    merged.fenceType = exact;
  } else {
    const hint = FENCE_TYPE_HINTS.find(([, pattern]) => pattern.test(merged.fenceType));
    // No hint matches: leave the words alone rather than guessing. The ranking step will find
    // nobody and say so, which is a better answer than quoting the wrong kind of fence.
    if (hint) merged.fenceType = hint[0];
  }
}

// Fences run roughly 600-2400mm, i.e. 60-240cm or 0.6-2.4m, and those three ranges barely
// overlap: under 10 was metres, 10-300 was centimetres (nothing is a 150mm fence, while a
// 150cm one is standard), above 300 is already millimetres. lengthMeters gets no such guard
// on purpose — a 600m rural boundary is a genuine answer, so there is no out-of-range value
// to key off, and the prompt handles that one instead.
if (merged.heightMm !== null && merged.heightMm !== undefined) {
  const height = merged.heightMm;
  if (Number.isFinite(height) && height > 0) {
    merged.heightMm = height < 10 ? Math.round(height * 1000) : height <= 300 ? Math.round(height * 10) : Math.round(height);
  }
}

// existingPrice rides along on the checklist but is never required — it only decides whether
// the results read as "vs the market" or "vs the quote you already have".
if (known.existingPrice !== null && known.existingPrice !== undefined && (merged.existingPrice === null || merged.existingPrice === undefined)) {
  merged.existingPrice = known.existingPrice;
}

const checklist = Object.keys(merged).length > 0 ? merged : null;
// siteAccess prices the removal and nothing else, so with no removal there is nothing to ask.
const isMissing = (field) => {
  if (!checklist) return true;
  // A suburb nobody confirmed against Google is not established, whoever wrote it down — the
  // agent, or a quote document it read. Without a place there are no coordinates, and the
  // ranking step matches on distance, so a name on its own can never produce a quote. Treating
  // it as missing is what makes the question get asked, which is what puts the picker on screen.
  if (field === 'suburb' && !place) return true;
  if (field === 'siteAccess' && checklist.removeOldFence === false) return false;
  return checklist[field] === null || checklist[field] === undefined;
};
const missing = FIELDS.filter(isMissing);
const nextField = missing[0];

let type = ['question', 'confirmation'].includes(parsed.type) ? parsed.type : 'message';
let message = typeof parsed.message === 'string' ? parsed.message.trim() : '';
let options = Array.isArray(parsed.options) ? parsed.options : [];

// Nothing downstream can recover from an empty bubble, so never emit one: fall back to
// the question that was actually due, or to an honest apology if the brief is finished.
if (!message) {
  message = nextField
    ? ASK[nextField].message
    : "Sorry, something went wrong on my end — mind trying that again in a moment?";
  if (nextField) {
    type = ASK[nextField].options.length ? 'question' : 'message';
    options = ASK[nextField].options;
  } else {
    type = 'message';
    options = [];
  }
}

// The model decides when to recap and when to hand off, and it sometimes does both
// early — recapping after three answers, then (once the user confirms) carrying on
// with the fields it never asked about. Both are only valid with all six known.
// The agent thinks it already has the suburb — it read the name off a message or an attached
// document — so it will never ask again of its own accord, and only asking puts the picker in
// front of the customer. Nothing else in the system can turn a name into a place, so the
// question goes back deterministically.
if (checklist && checklist.suburb && !place) {
  type = 'message';
  message = ASK.suburb.message;
  options = [];
}

if (missing.length > 0) {
  if (type === 'confirmation') {
    type = ASK[nextField].options.length ? 'question' : 'message';
    message = ASK[nextField].message;
    options = ASK[nextField].options;
  }
}

// Which field the client should collect with something other than a plain text box. Only the
// suburb qualifies: a mistyped suburb doesn't fail loudly, it silently matches zero businesses,
// so the client swaps its reply box for a Google-backed suburb picker and sends back a real
// place. Derived from the checklist, never from the model — 'suburb' is first in FIELDS, so it
// is the field due whenever it is still missing. The empty-options guard keeps the picker off a
// turn that is asking something else (every other field is answered by tapping an option).
// Every other check here is also true on the opening "can I ask you a few questions?"
// greeting — the suburb is still missing and a greeting carries no options either — so the
// message itself has to say what it is asking for. Deterministic on purpose: the alternative
// is trusting the model to label its own turn, and it is the model getting this wrong that
// put a suburb picker on the greeting in the first place.
const asksForSuburb = /\bsuburbs?\b|\bpost ?code\b/i.test(message);
const expectsSuburb = nextField === 'suburb' && options.length === 0 && asksForSuburb;

return [{
  json: {
    sessionId,
    // Kept for the client, which words the results headline differently for a direct
    // comparison — but derived from the brief now instead of a classifier that could flip
    // mid-conversation and hand the job to a second agent with a different checklist.
    intent: checklist && checklist.existingPrice !== null && checklist.existingPrice !== undefined ? 'compare_quote' : 'new_quote',
    place,
    type,
    message,
    options,
    // Absent, not null, when there is nothing special to collect — an older client that
    // doesn't know this field is unaffected either way.
    ...(expectsSuburb ? { expects: 'suburb' } : {}),
    // What the customer or their document called the place. Not an answer — a head start for
    // the picker, which still makes them confirm it against Google.
    ...(expectsSuburb && typeof parsed.suggestedSuburb === 'string' && parsed.suggestedSuburb.trim()
      ? { suggestedSuburb: parsed.suggestedSuburb.trim() }
      : {}),
    // Ranking runs off this flag, so it only flips once every field genuinely has a value.
    checklistComplete: missing.length === 0 && !!parsed.checklistComplete,
    checklist,
    results: [],
    avgRatePerMeter: null,
  },
}];

// Which businesses can actually take this job. Two gates, in this order:
//
//   1. SUBURB — the business's registered service area must BE the customer's suburb. This is
//      absolute: a Darwin business never appears for a Pakenham customer, no matter how large
//      a radius it has saved. Filling three result cards is not worth showing somebody a
//      business 3,000 km away.
//   2. RADIUS — inside that suburb, the business's own travel radius must still reach them.
//
// The match is on Google's placeId, not on the spelling of the suburb: the business stored one
// when it signed up and the customer's picker returns one, and they are the same id for the
// same place. Name is only a fallback for records saved before the id was kept.
const gate = $('Format New-Quote Result1').first().json;
const checklist = gate.checklist || {};
const place = gate.place;

const TRADE = 'fencing';

// Free text and stored slugs never agree on case or separators ('Pool Fencing' typed by a
// customer vs 'pool-fencing' saved at signup), so both sides are reduced to one shape before
// they are ever compared. A silent mismatch here reads as "nobody can do this job".
const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Firestore values arrive plain through the n8n node, but a raw REST shape ({ doubleValue })
// costs one line to tolerate and saves a whole class of "why is everything zero".
const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

// Haversine, in metres. A spherical earth is well inside the error a 25 km service radius
// already tolerates.
const distanceMeters = (fromLat, fromLng, toLat, toLng) => {
  const R = 6371000;
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(toLat - fromLat);
  const dLng = rad(toLng - fromLng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(fromLat)) * Math.cos(rad(toLat)) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
};

const lat = place ? num(place.latitude) : null;
const lng = place ? num(place.longitude) : null;
// No coordinates is a different failure from "nobody covers you", and the customer is told so
// rather than being shown an empty page.
if (lat === null || lng === null) return [{ json: { noMatch: true, noMatchReason: 'place' } }];

// placeIds are opaque and case-sensitive, so they are compared as-is; only the human-typed
// name gets normalised.
const wantedPlaceId = String((place && place.placeId) || '').trim();
const wantedSuburb = slug((place && (place.suburb || place.name)) || checklist.suburb);

const matches = [];
let outsideRadius = 0;
for (const item of $input.all()) {
  const business = item.json || {};
  const services = Array.isArray(business.services_provided) ? business.services_provided.map(slug) : [];
  if (!services.includes(TRADE)) continue;

  const area = business.serviceArea || {};
  const areaPlaceId = String(area.id || '').trim();
  const sameSuburb = areaPlaceId && wantedPlaceId
    ? areaPlaceId === wantedPlaceId
    : !!wantedSuburb && slug(area.name) === wantedSuburb;
  if (!sameSuburb) continue;

  const areaLat = num(area.latitude);
  const areaLng = num(area.longitude);
  const radius = num(area.radiusMeters);
  if (areaLat === null || areaLng === null || radius === null) continue;

  const distance = distanceMeters(lat, lng, areaLat, areaLng);
  // Right suburb, but they don't travel that far within it.
  if (distance > radius) { outsideRadius += 1; continue; }

  matches.push({
    json: {
      uid: business.uid,
      businessName: business.businessName || 'Unnamed business',
      rating: num(business.rating),
      reviewCount: num(business.reviewCount),
      isAutoAcceptEnabled: business.isAutoAcceptEnabled === true,
      // Separate from the one above on purpose: that toggle governs jobs from the web form,
      // this one governs jobs that came through this assistant. It decides whether the job
      // lands in the business's accepted_jobs or waits in incoming_jobs.
      autoAcceptsAi: business.isAiAutoAcceptEnabled === true,
      distanceMeters: Math.round(distance),
      distanceKm: Math.round(distance / 100) / 10,
      suburb: (place && place.displayLabel) || checklist.suburb || '',
    },
  });
}

if (matches.length === 0) {
  return [{ json: { noMatch: true, noMatchReason: outsideRadius > 0 ? 'radius' : 'suburb' } }];
}
// Nearest first, so the pricing reads that follow happen in a sensible order. Price, not
// distance, decides the actual ranking.
matches.sort((a, b) => a.json.distanceMeters - b.json.distanceMeters);
return matches;

// Nobody's service area reaches this customer — or we never got coordinates to check against.
// Either way this belongs back in the chat thread, where the suburb can be corrected in one
// line, not on an empty results page.
const gate = $('Format New-Quote Result1').first().json;
const reason = $input.first().json.noMatchReason || 'area';

return [{
  json: {
    sessionId: gate.sessionId || null,
    intent: gate.intent,
    type: 'result',
    message: reason === 'place'
      ? "I couldn't place that suburb on the map. Could you pick it from the suggestions?"
      : reason === 'radius'
        ? "There are fencing businesses in that suburb, but none of them travel far enough to reach you."
        : "No fencing business has registered that suburb yet. Try a nearby suburb?",
    options: [],
    results: [],
    avgRatePerMeter: null,
    comparison: null,
    noMatchReason: reason,
    checklist: gate.checklist,
    checklistComplete: true,
  },
}];

// Every business that covers the customer, priced off its own published rates, ranked cheapest
// first. One pricing doc per business arrives here, in the same order the filter emitted them.
const gate = $('Format New-Quote Result1').first().json;
const checklist = gate.checklist || {};
const sessionId = gate.sessionId || null;
const intent = gate.intent;
const covering = $('Filter Businesses by Service Area').all();

// Free text and stored slugs never agree on case or separators ('Pool Fencing' typed by a
// customer vs 'pool-fencing' saved at signup), so both sides are reduced to one shape before
// they are ever compared. A silent mismatch here reads as "nobody can do this job".
const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Firestore values arrive plain through the n8n node, but a raw REST shape ({ doubleValue })
// costs one line to tolerate and saves a whole class of "why is everything zero".
const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null)
    : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

const wanted = slug(checklist.fenceType);

// Every figure the customer sees, and every figure compared against theirs, is what they
// would actually pay. Some businesses publish GST-inclusive rates and some do not, and the
// customer's own quote almost always includes it — so an exclusive rate looks 10% cheaper
// than it is. Left alone, "beat my quote" would happily show them something dearer.
const GST_MULTIPLIER = 1.1;
const payable = (amount, gstInclusive) => (gstInclusive ? amount : Math.round(amount * GST_MULTIPLIER));
// Rates are keyed by height in metres: 1800mm is published as "1.8".
const heightMm = num(checklist.heightMm);
const heightKey = heightMm === null ? null : String(heightMm / 1000);

// The customer gives an exact length and the business publishes an exact rate, so the total is
// exact as well. The ±3% band that used to sit around it was expressing the uncertainty of a
// length bucket, and there are no buckets any more.
const lengthMetres = num(checklist.lengthMeters);
const quotes = [];
let blockedByType = 0;
let blockedByHeight = 0;

const pricingItems = $input.all();
for (let index = 0; index < pricingItems.length; index += 1) {
  const business = (covering[index] || {}).json || {};
  const pricing = pricingItems[index].json || {};
  if (!business.uid || pricing.isComplete !== true) continue;

  const enabled = Array.isArray(pricing.enabledTypes) ? pricing.enabledTypes.map(slug) : [];
  if (!enabled.includes(wanted)) { blockedByType += 1; continue; }

  // rates is keyed by the business's own spelling of the type, so find the key that means the
  // same thing rather than assuming ours matches theirs.
  const rates = pricing.rates || {};
  const rateKey = Object.keys(rates).find((key) => slug(key) === wanted);
  const rate = rateKey && heightKey !== null ? num((rates[rateKey] || {})[heightKey]) : null;
  // A business that publishes no rate at this height cannot quote it. Dropping it is right;
  // inventing a number from a neighbouring height would not be their price.
  if (rate === null) { blockedByHeight += 1; continue; }

  const removal = pricing.removal || {};
  const removalRate =
    checklist.removeOldFence === true && removal.offered === true ? (num(removal[checklist.siteAccess]) || 0) : 0;

  const gstInclusive = pricing.gstInclusive === true;
  const perMeter = rate + removalRate;
  // The floor is a real price too, so it is put on the same basis as the rest.
  const minimumCharge = payable(num(pricing.minimumCharge) || 0, gstInclusive);
  const total = Math.max(payable(Math.round(perMeter * (lengthMetres || 0)), gstInclusive), minimumCharge);

  const badges = [];
  // GST is per business and some publish inclusive, some not — the label goes on every card so
  // a cheaper-looking number is never just a missing 10%.
  badges.push(gstInclusive ? 'incl. GST' : 'incl. GST (added)');
  // Same suburb by definition, so this answers "whereabouts in my suburb are they?" — it is
  // 0.0 km whenever a business registered the suburb centre itself rather than its address.
  badges.push(business.distanceKm > 0 ? business.distanceKm + ' km away' : 'In your suburb');
  if (business.rating) badges.push(business.reviewCount ? business.rating + '★ (' + business.reviewCount + ')' : business.rating + '★');
  if (removalRate > 0) badges.push('Removal included');
  if (business.isAutoAcceptEnabled) badges.push('Instant accept');

  quotes.push({
    uid: business.uid,
    businessName: business.businessName,
    suburb: business.suburb,
    distanceKm: business.distanceKm,
    ratePerMeter: payable(rate, gstInclusive),
    removalPerMeter: payable(removalRate, gstInclusive),
    minimumCharge,
    gstInclusive,
    // Travels to the client so the saved job can go straight into this business's
    // accepted_jobs instead of waiting in incoming_jobs.
    autoAcceptsAi: business.autoAcceptsAi === true,
    currency: pricing.currency || 'AUD',
    projectTotalMin: total,
    projectTotalMax: total,
    estimatedTotal: total,
    badges,
  });
}

quotes.sort((a, b) => a.projectTotalMin - b.projectTotalMin || b.ratePerMeter - a.ratePerMeter);

const existingPrice = num(checklist.existingPrice);
// What businesses round here charge for this job — every one that could quote it, not just
// the handful shown. Averaging only the cheapest three would flatter the result and make the
// saving look smaller than it is.
const average = quotes.length > 0 ? Math.round(quotes.reduce((sum, q) => sum + q.projectTotalMin, 0) / quotes.length) : null;

// "Beat this price" has one honest answer: only what actually beats it. One result is a
// result; none is an answer too. Showing something dearer would turn the whole feature into
// its opposite, so anything at or above their number is dropped here.
const beating = existingPrice === null ? quotes : quotes.filter((quote) => quote.projectTotalMin < existingPrice);
const top = beating.slice(0, 3);

if (top.length === 0 && existingPrice !== null && quotes.length > 0) {
  const closest = quotes[0].projectTotalMin;
  return [{ json: { sessionId, intent, type: 'result',
    message: 'Nobody covering your suburb came in under $' + existingPrice.toLocaleString() +
      '. The closest was $' + closest.toLocaleString() + ', so the quote you have is already a good one.',
    options: [], results: [], avgRatePerMeter: null, comparison: null, noMatchReason: 'notCheaper',
    checklist, checklistComplete: true } }];
}

if (top.length === 0) {
  // Say which wall they hit: a fence type nobody nearby does is a different problem from a
  // height nobody prices, and only one of them is worth changing the answer for.
  const reason = blockedByType > 0 && blockedByHeight === 0 ? 'fenceType' : blockedByHeight > 0 ? 'height' : 'pricing';
  const message = reason === 'fenceType'
    ? 'The businesses near you do not offer that fence type yet. Want to try a different type?'
    : reason === 'height'
      ? 'Nobody near you publishes a rate at that height. Want to try a different height?'
      : 'I found businesses near you, but none of them have finished setting up their pricing yet.';
  return [{ json: { sessionId, intent, type: 'result', message, options: [], results: [], avgRatePerMeter: null, comparison: null, noMatchReason: reason, checklist, checklistComplete: true } }];
}

const benchmark = existingPrice === null ? average : existingPrice;
const cheapest = top[0].projectTotalMin;

return [{
  json: {
    sessionId,
    intent,
    type: 'result',
    message: 'Here are the local businesses that cover your job.',
    options: [],
    // The client's existing shape, so the results page needs no change to render these.
    results: top.map((quote) => ({
      businessId: quote.uid,
      autoAcceptsAi: quote.autoAcceptsAi,
      businessName: quote.businessName,
      suburb: quote.suburb,
      ratePerMeter: quote.ratePerMeter,
      estimatedTotal: quote.estimatedTotal,
      notes: quote.badges.join(' · '),
    })),
    avgRatePerMeter: Math.round(top.reduce((sum, q) => sum + q.ratePerMeter, 0) / top.length),
    comparison: {
      potentialSavings: benchmark > cheapest ? benchmark - cheapest : null,
      marketAverage: average,
      // Every business that covers them, including the ones that could not quote this job or
      // came in above their price — that is what "screened" honestly means.
      totalQuotesScreened: covering.length,
      userExistingPrice: existingPrice,
      quotes: top.map((quote) => ({
        businessId: quote.uid,
        autoAcceptsAi: quote.autoAcceptsAi,
        businessName: quote.businessName,
        ratePerMeter: quote.ratePerMeter,
        projectTotalMin: quote.projectTotalMin,
        projectTotalMax: quote.projectTotalMax,
        badges: quote.badges,
        tag: quote.projectTotalMin === cheapest ? 'BEST_VALUE' : null,
        savingsFromAverage: benchmark > quote.projectTotalMin ? benchmark - quote.projectTotalMin : null,
        suburb: quote.suburb,
      })),
    },
    checklist,
    checklistComplete: true,
  },
}];
